#ifndef CONTAINERS_HEAP_TIMER_H
#define CONTAINERS_HEAP_TIMER_H

#include "log.h"
#include "util.h"
#include <algorithm>
#include <cassert>
#include <chrono>
#include <compare>
#include <deque>
#include <functional>
#include <optional>
#include <stdexcept>
#include <unordered_map>

namespace ws {

template <typename Key>
class HeapTimer {
public:
    using Clock = std::chrono::steady_clock;
    using TimeOutCallback = std::function<void(const Key&)>;

    explicit HeapTimer(log::Logger::Ptr logger = log::RootLogger()) noexcept : logger_(std::move(logger)) {}

    HeapTimer(const HeapTimer&) = delete;
    HeapTimer(HeapTimer&&) = delete;
    HeapTimer& operator=(const HeapTimer&) = delete;
    HeapTimer& operator=(HeapTimer&&) = delete;

    void Adjust(const Key& key, Clock::duration expiration) {
        Adjust(key, Clock::now() + expiration);
    }

    void Adjust(const Key& key, Clock::time_point expiration) {
        Adjust(key, expiration, std::nullopt);
    }

    void Push(const Key& key, Clock::duration expiration, TimeOutCallback callback) noexcept {
        Push(key, Clock::now() + expiration, std::move(callback));
    }

    void Push(const Key& key, Clock::time_point expiration, TimeOutCallback callback) noexcept {
        if (key_to_idx_.find(key) != key_to_idx_.end()) {
            Adjust(key, expiration, std::move(callback));
            return;
        }
        nodes_.emplace_back(Node{key, expiration, std::move(callback)});
        key_to_idx_[key] = nodes_.size() - 1;
        ShiftUp(nodes_.size() - 1);
    }

    void Tick() noexcept {
        while (!nodes_.empty() && nodes_.front().Expired()) {
            auto node = std::move(nodes_.front());
            key_to_idx_.erase(node.key);
            try {
                node.callback(node.key);
            } catch (const std::exception& e) {
                logger_->Log(log::LogLevel::Error, "Callback failed: {}", e.what());
            }
            Pop();
        }
    }

    bool Remove(const Key& key) noexcept {
        if (auto it = key_to_idx_.find(key); it != key_to_idx_.end()) {
            RemoveByIndex(it->second);
            return true;
        }
        return false;
    }

    void Invoke(const Key& key) {
        if (auto it = key_to_idx_.find(key); it != key_to_idx_.end()) {
            auto node = std::move(nodes_[it->second]);
            RemoveByIndex(it->second);
            try {
                node.callback(node.key);
            } catch (const std::exception& e) {
                logger_->Log(log::LogLevel::Error, "Callback failed: {}", e.what());
            }
        } else {
            throw std::out_of_range("Key not found in timer system");
        }
    }

    Key Pop() noexcept {
        assert(!nodes_.empty());
        Swap(0, nodes_.size() - 1);
        auto key = nodes_.back().key;
        key_to_idx_.erase(key);
        nodes_.pop_back();
        ShiftDown(0);
        return key;
    }

    void Clear() noexcept {
        nodes_.clear();
        key_to_idx_.clear();
    }

    bool Contain(const Key& key) const noexcept {
        return key_to_idx_.find(key) != key_to_idx_.end();
    }

    bool Empty() const noexcept {
        return nodes_.empty();
    }

    std::size_t Size() const noexcept {
        return nodes_.size();
    }

    Clock::duration ToNextTick() noexcept {
        Tick();
        if (nodes_.empty()) {
            return Clock::duration{};
        }
        return nodes_.front().expiration - Clock::now();
    }

private:
    struct Node {
        Key key;
        Clock::time_point expiration;
        TimeOutCallback callback;

        bool Expired() const noexcept {
            return expiration <= Clock::now();
        }

        void Swap(Node& other) noexcept {
            std::swap(key, other.key);
            std::swap(expiration, other.expiration);
            std::swap(callback, other.callback);
        }

        auto operator<=>(const Node&) const = default;
    };

    void Adjust(const Key& key, Clock::time_point expiration, std::optional<TimeOutCallback> callback) {
        if (auto it = key_to_idx_.find(key); it != key_to_idx_.end()) {
            auto idx = it->second;
            nodes_[idx].expiration = expiration;
            if (callback) {
                nodes_[idx].callback = *std::move(callback);
            }
            ShiftUp(idx);
            ShiftDown(idx);
        } else {
            throw std::out_of_range("Key not found in timer system");
        }
    }

    Key RemoveByIndex(std::size_t idx) noexcept {
        Swap(idx, nodes_.size() - 1);
        auto key = nodes_.back().key;
        key_to_idx_.erase(key);
        nodes_.pop_back();
        if (idx < nodes_.size()) {
            ShiftUp(idx);
            ShiftDown(idx);
        }
        return key;
    }

    void ShiftUp(std::size_t idx) noexcept {
        while (auto parent_idx = Parent(idx); parent_idx && nodes_[*parent_idx] > nodes_[idx]) {
            Swap(*parent_idx, idx);
            idx = *parent_idx;
        }
    }

    void ShiftDown(std::size_t idx) noexcept {
        while (auto child_idx = SmallChild(idx); child_idx && nodes_[*child_idx] < nodes_[idx]) {
            Swap(*child_idx, idx);
            idx = *child_idx;
        }
    }

    bool ValidIndex(std::size_t idx) const noexcept {
        return idx < nodes_.size();
    }

    std::optional<std::size_t> Parent(std::size_t idx) const noexcept {
        if (idx == 0) {
            return std::nullopt;
        }
        return (idx - 1) / 2;
    }

    std::optional<std::size_t> SmallChild(std::size_t idx) const noexcept {
        auto left = 2 * idx + 1;
        auto right = 2 * idx + 2;
        if (!ValidIndex(left)) {
            return std::nullopt;
        }
        if (!ValidIndex(right)) {
            return left;
        }
        return nodes_[left] < nodes_[right] ? left : right;
    }

    void Swap(const std::size_t idx1, const std::size_t idx2) noexcept {
        nodes_[idx1].Swap(nodes_[idx2]);
        key_to_idx_[nodes_[idx1].key] = idx1;
        key_to_idx_[nodes_[idx2].key] = idx2;
    }

private:
    log::Logger::Ptr logger_;
    std::unordered_map<Key, std::size_t> key_to_idx_;
    std::deque<Node> nodes_;
};

}

#endif // CONTAINERS_HEAP_TIMER_H
